'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID(),today=()=>new Date().toLocaleDateString('en-CA');
const colors=['#7866e9','#5bbba2','#f2b65e','#e9809b','#6ba4e3','#b58bd6'];
let db,state,docs=[],vaultTab='all',query='',collectionFilter='',typeFilter='',groupId='',period='all',payerFilter='',toastTimer,previewURL;
const main=$('#main');
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
function request(req){return new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
// One completed transaction is the unit of persistence; expense writes are serialized by IndexedDB.
async function transaction(stores,work){return new Promise((resolve,reject)=>{const tx=db.transaction(stores,'readwrite');let result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Storage update cancelled.'));try{work(tx,v=>result=v);}catch(e){tx.abort();reject(e);}});}
async function load(){const tx=db.transaction(['state','documents'],'readonly');[state,docs]=await Promise.all([request(tx.objectStore('state').get('main')),request(tx.objectStore('documents').getAll())]);state ||= {version:1,name:'Santosh',theme:'system',collections:[],groups:[]};}
async function mutate(fn){await transaction(['state'],(tx)=>{const store=tx.objectStore('state'),r=store.get('main');r.onsuccess=()=>{try{const s=r.result||state;fn(s);store.put(s,'main');}catch(e){toast(e.message);tx.abort();}};});await load();render();}
function group(){return state.groups.find(g=>g.id===groupId)||state.groups[0];}
function member(g,id){return g.members.find(m=>m.id===id)?.name||'Unknown';}
function currency(g,n){return new Intl.NumberFormat('en-CA',{style:'currency',currency:g.currency}).format(n/100);}
function date(v){return new Date(v+'T12:00:00').toLocaleDateString('en-CA',{month:'short',day:'numeric',year:'numeric'});}
function currentRoute(){return ['vault','expenses'].includes(location.hash.slice(1))?location.hash.slice(1):'home';}
function heading(label,title,sub,action=''){return `<div class="heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function empty(icon,title,text,button=''){return `<div class="empty panel"><div class="tile-icon">${icon}</div><h2>${title}</h2><p>${text}</p>${button}</div>`;}
function render(){document.body.classList.toggle('dark',state.theme==='dark'||(state.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches));$('#profile-name').innerHTML=`${esc(state.name)}<small>Personal workspace</small>`;$('.avatar').textContent=state.name.slice(0,1).toUpperCase();const route=currentRoute();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route));$('#breadcrumb').textContent='Your space / '+({home:'Overview',vault:'Personal Vault',expenses:'Expense Sharing'}[route]);if(route==='home')home();else if(route==='vault')vault();else expenses();}
function home(){const count=state.groups.length;main.innerHTML=heading('YOUR EVERYDAY, TOGETHER',`Hi, ${esc(state.name)}.`,"A little space for the things that matter.",`<span class="date-pill">${new Date().toLocaleDateString('en-CA',{weekday:'short',month:'long',day:'numeric'})}</span>`)+`<section class="hero"><div><span class="eyebrow">LESS CLUTTER. MORE CLARITY.</span><h2 style="margin-top:10px">Everything in your orbit.</h2><p>Your documents, shared expenses, and a little room for what comes next.</p></div><div class="hero-art" aria-hidden="true"><div class="ring"></div><div class="ring"></div><div class="orb">◉</div></div></section><div class="section-label"><h2>Your tools</h2><span>One space. Everyday essentials.</span></div><section class="tools"><a class="tool" href="#vault"><div class="tool-head"><div class="tile-icon">▤</div><span class="pill">LOCAL VAULT</span></div><h2>Personal Vault</h2><p>A home for your documents.<br>Organized and easy to find.</p><div class="tool-bottom"><span>${docs.length} documents · ${state.collections.length} collections</span><span class="arrow">↗</span></div></a><a class="tool" href="#expenses"><div class="tool-head"><div class="tile-icon green">◔</div><span class="pill">KEEP IT FAIR</span></div><h2>Expense Sharing</h2><p>Split the cost. Keep the clarity.<br>Know who owes whom.</p><div class="tool-bottom"><span>${count} ${count===1?'group':'groups'} on this device</span><span class="arrow">↗</span></div></a>${[1,2].map(()=>`<div class="tool soon"><div class="tool-head"><div class="tile-icon">＋</div><span class="pill">Coming Soon</span></div><h3>Room for something new.</h3><p>More possibilities, at your pace.</p></div>`).join('')}</section><div class="note"><strong>Your device. Your space.</strong> Files and records stay in this browser. No login or cloud connection is active. <button data-action="settings" class="quiet">Settings & backups →</button></div>`;}
function vault(){let shown=docs.filter(d=>(vaultTab!=='favorites'||d.favorite)&&(!query||d.name.toLowerCase().includes(query.toLowerCase()))&&(!collectionFilter||d.collection===collectionFilter)&&(!typeFilter||d.type.startsWith(typeFilter))).sort((a,b)=>b.created.localeCompare(a.created));main.innerHTML=heading('PERSONAL VAULT','Keep the important things close.','Your files, organized on this device.',`<button class="primary" data-action="upload">＋ Upload files</button>`)+`<div class="stats"><div class="stat"><span>Documents</span><strong>${docs.length}</strong></div><div class="stat"><span>Collections</span><strong>${state.collections.length}</strong></div><div class="stat"><span>Favorites</span><strong>${docs.filter(d=>d.favorite).length}</strong></div><div class="stat"><span>Stored locally</span><strong>${size(docs.reduce((n,d)=>n+d.size,0))}</strong></div></div><div class="tabs">${[['all','My Documents'],['favorites','Favorites'],['collections','Collections']].map(([id,label])=>`<button data-tab="${id}" class="${vaultTab===id?'selected':''}">${label}</button>`).join('')}</div>`;
if(vaultTab==='collections'){main.innerHTML+=`<div class="toolbar"><button data-action="collection" class="primary">＋ New collection</button></div>`+(state.collections.length?`<div class="documents">${state.collections.map(c=>`<article class="document"><div class="file-icon">▱</div><h3>${esc(c.name)}</h3><small>${docs.filter(d=>d.collection===c.id).length} documents</small><div class="doc-actions"><button data-open-collection="${c.id}">Open</button><button data-delete-collection="${c.id}">Delete</button></div></article>`).join('')}</div>`:empty('▱','A place for everything','Create a collection to organize your files.'));return;}
main.innerHTML+=`<div class="toolbar"><input id="search" aria-label="Search documents" placeholder="Search your documents…" value="${esc(query)}"><select id="collection-filter" aria-label="Filter collection"><option value="">All collections</option>${state.collections.map(c=>`<option value="${c.id}" ${collectionFilter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="type-filter" aria-label="Filter file type"><option value="">All file types</option>${[['image/','Images'],['application/pdf','PDF'],['text/plain','Text']].map(([id,v])=>`<option value="${id}" ${typeFilter===id?'selected':''}>${v}</option>`).join('')}</select></div>`+(shown.length?`<div class="documents">${shown.map(d=>`<article class="document"><div class="file-icon">${d.type.startsWith('image/')?'▧':d.type==='application/pdf'?'▤':'▥'}</div><h3>${esc(d.name)}</h3><small>${size(d.size)} · ${date(d.created.slice(0,10))}</small><small>${esc(state.collections.find(c=>c.id===d.collection)?.name||'Unfiled')}</small><div class="doc-actions"><button data-preview="${d.id}">Open</button><button data-favorite="${d.id}" aria-label="${d.favorite?'Remove favorite':'Favorite'}">${d.favorite?'★':'☆'}</button><button data-organize="${d.id}">Move</button><button data-delete-doc="${d.id}" aria-label="Delete ${esc(d.name)}">×</button></div></article>`).join('')}</div>`:empty('▤',query||collectionFilter||typeFilter?'No matching documents':'Your vault starts here','Upload files to keep them organized. Up to 20 MB per file.',`<button data-action="upload" class="primary">Upload your first file</button>`))+`<div class="note">Local storage is not encrypted or backed up automatically. Clearing browser data can remove these files. Download a backup in Settings.</div>`;}
function size(n){return n>=1e6?(n/1e6).toFixed(1)+' MB':Math.round(n/1000)+' KB';}
function inPeriod(e){if(period==='all')return true;const now=new Date(),dt=new Date(e.date+'T12:00:00');return period==='month'?dt.getMonth()===now.getMonth()&&dt.getFullYear()===now.getFullYear():dt.getFullYear()===now.getFullYear();}
function expenses(){const g=group();main.innerHTML=heading('EXPENSE SHARING','Good times. Fair shares.','Keep track of shared costs, without the guesswork.',`<button data-action="group" class="primary">＋ New group</button>`);if(!g){main.innerHTML+=empty('◔','Start with your people','Create a local group, add members, and split your first expense.',`<button data-action="group" class="primary">Create a group</button>`)+`<div class="note">Members are names on this device. Invitations and shared online records will be added with accounts later.</div>`;return;}groupId=g.id;const all=g.expenses.filter(inPeriod),shown=all.filter(e=>!payerFilter||e.payer===payerFilter),total=all.reduce((n,e)=>n+e.amount,0),b=Money.balances(g),me=g.me;const byPayer=g.members.map((m,i)=>({...m,color:colors[i%colors.length],total:all.filter(e=>e.payer===m.id).reduce((n,e)=>n+e.amount,0)})).filter(m=>m.total>0);let pos=0;const gradient=byPayer.map(m=>{const start=pos;pos+=m.total/total*100;return `${m.color} ${start}% ${pos}%`;}).join(',');main.innerHTML+=`<div class="toolbar"><select id="group-select" aria-label="Select group">${state.groups.map(x=>`<option value="${x.id}" ${g.id===x.id?'selected':''}>${esc(x.name)} · ${x.currency}</option>`).join('')}</select><select id="period" aria-label="Spending period"><option value="all">All time</option><option value="month" ${period==='month'?'selected':''}>This month</option><option value="year" ${period==='year'?'selected':''}>This year</option></select><button data-action="member">＋ Add member</button><button data-action="expense" class="primary">＋ Add expense</button><button data-action="repayment">Record repayment</button></div><div class="stats"><div class="stat"><span>Group spending · selected period</span><strong>${currency(g,total)}</strong></div><div class="stat"><span>Your share · selected period</span><strong>${currency(g,all.reduce((n,e)=>n+(e.allocations[me]||0),0))}</strong></div><div class="stat"><span>You owe · full ledger</span><strong class="negative">${currency(g,Math.max(0,-b[me]))}</strong></div><div class="stat"><span>You are owed · full ledger</span><strong class="positive">${currency(g,Math.max(0,b[me]))}</strong></div></div><section class="panel"><div class="section-label" style="margin-top:0"><h2>Spending at a glance</h2><span>By payer · ${period==='all'?'All time':period==='month'?'This month':'This year'}</span></div><div class="chart-layout"><div class="donut-wrap"><div class="donut" role="img" aria-label="Spending by payer: ${esc(byPayer.map(m=>m.name+' '+currency(g,m.total)).join(', ')||'No expenses')}" style="${gradient?'background:conic-gradient('+gradient+')':''}"><div class="donut-hole"><span>Group spending</span><strong>${currency(g,total)}</strong><span>${g.currency}</span></div></div></div><div class="legend"><p class="muted">Select a payer to filter the table.</p>${byPayer.map(m=>`<button data-payer="${m.id}" aria-pressed="${payerFilter===m.id}"><span class="dot" style="background:${m.color}"></span>${esc(m.name)}<strong>${currency(g,m.total)}</strong><span>${(m.total/total*100).toFixed(0)}%</span></button>`).join('')||'<span class="muted">Your chart will appear after your first expense.</span>'}${payerFilter?'<button data-payer="">Show all payers ×</button>':''}</div></div></section><section class="panel"><div class="section-label" style="margin-top:0"><h2>Expense history</h2><span>${shown.length} expenses</span></div><div class="table-scroll"><table><thead><tr><th>Description</th><th>Date</th><th>Amount</th><th>Payer</th><th>Participants</th><th>Details</th></tr></thead><tbody>${shown.map(e=>`<tr><td>${esc(e.description)}</td><td>${date(e.date)}</td><td>${currency(g,e.amount)}</td><td>${esc(member(g,e.payer))}</td><td>${Object.keys(e.allocations).length} people</td><td><button data-detail="${e.id}">View split</button></td></tr>`).join('')||'<tr><td colspan="6">No expenses in this view. Add an expense to get started.</td></tr>'}</tbody></table></div></section><div class="row"><section class="panel"><h2>Settle up</h2><p class="subtitle">Outstanding balances · full ledger, all dates</p>${Money.debts(g).map(d=>`<div class="balance-row"><span>${esc(member(g,d.from))} → ${esc(member(g,d.to))}</span><strong>${currency(g,d.amount)}</strong></div>`).join('')||'<p class="muted">All settled. A good place to be.</p>'}<p class="split-hint">Suggested transfers simplify net balances across the group.</p></section><section class="panel"><h2>Your people</h2><p class="subtitle">Local group · ${esc(g.name)}</p>${g.members.map(m=>`<div class="balance-row"><span>${esc(m.name)} ${m.id===me?'<span class="pill">You</span>':''}</span><span class="${b[m.id]>0?'positive':b[m.id]<0?'negative':'muted'}">${b[m.id]>0?'owed ':b[m.id]<0?'owes ':''}${currency(g,Math.abs(b[m.id]))}</span></div>`).join('')}</section></div><section class="panel"><h2>Repayment history</h2><p class="subtitle">Money already transferred outside Orbit. No payments are processed here.</p>${g.repayments.map(r=>`<div class="balance-row"><span>${esc(member(g,r.from))} → ${esc(member(g,r.to))}<small>${date(r.date)}</small></span><strong>${currency(g,r.amount)}</strong><button data-delete-repayment="${r.id}" class="quiet">Delete</button></div>`).join('')||'<p class="muted">No repayments recorded yet.</p>'}</section><div class="note">These records belong to this browser. Online invitations, member permissions, and synchronization are not active.</div>`;}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();}
function closeModal(){if(previewURL){URL.revokeObjectURL(previewURL);previewURL=null;}$('#modal').close();}
function field(label,control){return `<div class="field"><label>${label}${control}</label></div>`;}
function formModal(title,html,submit,button='Save'){modal(title,`<form id="form">${html}<p class="error" role="alert" id="form-error"></p><div class="form-actions"><button type="button" data-action="cancel">Cancel</button><button class="primary" type="submit">${button}</button></div></form>`);$('#form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{await submit(new FormData(e.target));closeModal();}catch(err){$('#form-error').textContent=err.message||'Could not save. Check browser storage.';btn.disabled=false;}};}
function options(g,selected){return g.members.map(m=>`<option value="${m.id}" ${m.id===selected?'selected':''}>${esc(m.name)}</option>`).join('');}
function settings(){formModal('Your workspace',field('Your name',`<input name="name" maxlength="60" required value="${esc(state.name)}">`)+field('Appearance',`<select name="theme">${['system','light','dark'].map(t=>`<option ${state.theme===t?'selected':''}>${t}</option>`).join('')}</select>`)+`<div class="note">No account or cloud backup is active. Anyone using this browser profile can open your workspace.</div><div class="toolbar" style="margin-top:18px"><button type="button" data-action="export">Download full backup</button><button type="button" data-action="restore">Restore backup</button><button type="button" data-action="persist">Request storage persistence</button></div><p class="subtitle">Backup includes document contents. Store it somewhere safe. Restore replaces this workspace after confirmation.</p>`,async f=>{await mutate(s=>{s.name=f.get('name').trim()||'Friend';s.theme=f.get('theme');});});}
function createGroup(){formModal('A new shared space',field('Group name',`<input name="name" required maxlength="80" placeholder="e.g. Our apartment">`)+field('Currency',`<select name="currency"><option>CAD</option><option>USD</option><option>NPR</option><option>EUR</option><option>GBP</option></select>`)+field('Other members · one name per line',`<textarea name="names" maxlength="1000" rows="4" placeholder="Danny&#10;Subash" style="width:100%;padding:12px;border:1px solid var(--line);border-radius:9px;background:var(--surface);color:var(--text)"></textarea>`)+`<p class="subtitle">You are included automatically. Member names are local records, not online accounts. Up to 30 members.</p>`,async f=>{const name=f.get('name').trim();if(!name)throw Error('Enter a group name.');const names=[state.name,...f.get('names').split('\n').map(v=>v.trim()).filter(Boolean)];if(names.length>30||names.some(n=>n.length>60)||new Set(names.map(n=>n.toLowerCase())).size!==names.length)throw Error('Use distinct member names, up to 60 characters each.');const members=names.map(name=>({id:uid(),name}));const g={id:uid(),name,currency:f.get('currency'),me:members[0].id,members,expenses:[],repayments:[]};await mutate(s=>{s.groups.push(g);});groupId=g.id;render();},'Create group');}
function addExpense(existing){const g=group(),operation=existing?.id||uid();formModal(existing?'Edit expense':'Add an expense',field('Description',`<input name="description" required maxlength="120" placeholder="What was it for?" value="${esc(existing?.description||'')}">`)+`<div class="row">${field('Amount · '+g.currency,`<input name="amount" required inputmode="decimal" placeholder="0.00" value="${existing?(existing.amount/100).toFixed(2):''}">`)}${field('Date',`<input name="date" type="date" required value="${existing?.date||today()}">`)}</div>`+field('Paid by',`<select name="payer">${options(g,existing?.payer||g.me)}</select>`)+field('Split method',`<select name="mode" id="split-mode"><option value="equal">Equally</option><option value="exact">Exact amounts</option><option value="percentage">Percentages</option><option value="shares">Shares</option></select>`)+`<label>Participants</label>${g.members.map(m=>`<div class="check-row"><input type="checkbox" name="participant" value="${m.id}" id="p-${m.id}" ${!existing||m.id in existing.allocations?'checked':''}><label for="p-${m.id}">${esc(m.name)}</label><input class="value" name="value-${m.id}" aria-label="Split value for ${esc(m.name)}" placeholder="Value" hidden></div>`).join('')}<p class="split-hint">Remainder cents go to the largest fractional shares; ties follow member order. Exact splits require a positive amount per selected person.</p>`,async f=>{const amount=Money.cents(f.get('amount')),ids=g.members.filter(m=>f.getAll('participant').includes(m.id)).map(m=>m.id),allocations=Money.split(amount,ids,f.get('mode'),ids.map(id=>f.get('value-'+id)));const dt=f.get('date');if(!/^\d{4}-\d{2}-\d{2}$/.test(dt)||isNaN(new Date(dt+'T12:00:00')))throw Error('Choose a valid date.');if(!f.get('description').trim())throw Error('Enter a description.');const expense={id:operation,description:f.get('description').trim(),amount,date:dt,payer:f.get('payer'),allocations,mode:f.get('mode'),created:new Date().toISOString()};await mutate(s=>{const target=s.groups.find(x=>x.id===g.id);if(!target)throw Error('Group no longer exists.');if(!target.members.some(m=>m.id===expense.payer)||ids.some(id=>!target.members.some(m=>m.id===id)))throw Error('Invalid group members.');const i=target.expenses.findIndex(x=>x.id===operation);if(existing){if(i<0)throw Error('Expense no longer exists.');target.expenses[i]=expense;}else if(i<0)target.expenses.push(expense);});});$('#split-mode').onchange=e=>document.querySelectorAll('.value').forEach(el=>{el.hidden=e.target.value==='equal';el.value=e.target.value==='shares'?'1':'';el.placeholder=e.target.value==='percentage'?'%':'Value';});}
function repay(){const g=group();formModal('Record a repayment',`<p class="muted">Record money already transferred by cash, e-transfer, or another method.</p>`+field('From',`<select name="from">${options(g)}</select>`)+field('To',`<select name="to">${options(g,g.members[1]?.id)}</select>`)+`<div class="row">${field('Amount · '+g.currency,'<input name="amount" inputmode="decimal" required placeholder="0.00">')}${field('Date',`<input name="date" type="date" required value="${today()}">`)}</div>`,async f=>{if(f.get('from')===f.get('to'))throw Error('Choose two different members.');if(!/^\d{4}-\d{2}-\d{2}$/.test(f.get('date')))throw Error('Choose a valid date.');const amount=Money.cents(f.get('amount')),id=uid();await mutate(s=>{const target=s.groups.find(x=>x.id===g.id);if(!target||![f.get('from'),f.get('to')].every(id=>target.members.some(m=>m.id===id)))throw Error('Invalid group members.');const b=Money.balances(target);if(amount>Math.min(Math.max(0,-b[f.get('from')]),Math.max(0,b[f.get('to')])))throw Error('Repayment exceeds these members’ outstanding net balances.');target.repayments.push({id,from:f.get('from'),to:f.get('to'),amount,date:f.get('date')});});});}
async function docWrite(work){await transaction(['documents'],tx=>work(tx.objectStore('documents')));await load();render();}
function upload(){const input=document.createElement('input');input.type='file';input.multiple=true;input.onchange=async()=>{try{if(input.files.length>20)throw Error('Upload at most 20 files at once.');const files=[...input.files];if(files.some(f=>f.size>20e6))throw Error('Each file must be 20 MB or smaller.');if(docs.length+files.length>2000||docs.reduce((n,d)=>n+d.size,0)+files.reduce((n,f)=>n+f.size,0)>80e6)throw Error('Local vault limit is 80 MB and 2,000 documents. Download a backup before removing files.');const newDocs=files.map(file=>({id:uid(),name:file.name,type:file.type||'application/octet-stream',size:file.size,created:new Date().toISOString(),favorite:false,collection:'',blob:file}));await docWrite(store=>newDocs.forEach(d=>store.add(d)));toast('Files saved in this browser.');}catch(e){toast(e.message||'Storage full. Download a backup and free space.');}};input.click();}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function preview(id){const d=docs.find(x=>x.id===id);if(!d)return;modal(d.name,`<div id="preview-content"></div><div class="form-actions"><button id="download-doc" class="primary">Download original</button></div>`);$('#download-doc').onclick=()=>download(d.blob,d.name);if(['image/jpeg','image/png','image/webp','image/gif'].includes(d.type)){previewURL=URL.createObjectURL(d.blob);const img=new Image();img.src=previewURL;img.alt=d.name;img.className='preview-image';$('#preview-content').append(img);}else if(d.type==='text/plain'){const pre=document.createElement('pre');pre.style.whiteSpace='pre-wrap';pre.textContent=(await d.blob.slice(0,200000).text());$('#preview-content').append(pre);}else $('#preview-content').innerHTML='<p class="muted">Preview is unavailable for this file type. Download it to open it in a suitable app.</p>';}
function detail(id){const g=group(),e=g.expenses.find(x=>x.id===id);modal('Expense details',`<h3>${esc(e.description)}</h3><p class="muted">${currency(g,e.amount)} · ${date(e.date)} · Paid by ${esc(member(g,e.payer))}</p>${Object.entries(e.allocations).map(([id,n])=>`<div class="balance-row"><span>${esc(member(g,id))}</span><strong>${currency(g,n)}</strong></div>`).join('')}<div class="form-actions"><button data-edit-expense="${e.id}">Edit expense</button><button data-delete-expense="${e.id}" class="danger">Delete expense</button></div>`);}
async function exportBackup(){toast('Preparing your backup…');const records=[];for(const d of docs){const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(d.blob);});const {blob,...metadata}=d;records.push({...metadata,data});}download(new Blob([JSON.stringify({format:'orbit-local',version:1,exported:new Date().toISOString(),state,documents:records})],{type:'application/json'}),'orbit-backup-'+today()+'.json');toast('Backup downloaded. It contains your private files.');}
function safeId(v){return typeof v==='string'&&/^[A-Za-z0-9_-]{1,80}$/.test(v);}
function validateBackup(data){if(data?.format!=='orbit-local'||data.version!==1||data.state?.version!==1||!Array.isArray(data.documents)||!Array.isArray(data.state.groups)||!Array.isArray(data.state.collections))throw Error('Unsupported backup format.');if(data.documents.reduce((n,d)=>n+(Number(d.size)||0),0)>80e6)throw Error('Backup exceeds the 80 MB vault limit.');const s=data.state;if(typeof s.name!=='string'||s.name.length>60||!['system','dark','light'].includes(s.theme)||s.groups.length>100||new Set(s.groups.map(g=>g.id)).size!==s.groups.length||data.documents.length>2000||s.collections.length>1000)throw Error('Invalid workspace.');const ids=new Set();for(const c of s.collections){if(!safeId(c.id)||typeof c.name!=='string'||ids.has(c.id))throw Error('Invalid collection.');ids.add(c.id);}for(const g of s.groups){if(!safeId(g.id)||typeof g.name!=='string'||!['CAD','USD','NPR','EUR','GBP'].includes(g.currency)||!Array.isArray(g.members)||g.members.length>30||!g.members.length||!Array.isArray(g.expenses)||!Array.isArray(g.repayments)||g.expenses.length>10000||g.repayments.length>10000||new Set(g.members.map(m=>m.id)).size!==g.members.length||!g.members.some(m=>m.id===g.me)||g.members.some(m=>!safeId(m.id)||typeof m.name!=='string'))throw Error('Invalid group.');for(const e of g.expenses){if(!safeId(e.id)||typeof e.description!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(e.date)||!e.allocations||typeof e.allocations!=='object')throw Error('Invalid expense.');}for(const r of g.repayments){if(!safeId(r.id)||!/^\d{4}-\d{2}-\d{2}$/.test(r.date))throw Error('Invalid repayment.');}if(new Set(g.expenses.map(e=>e.id)).size!==g.expenses.length||new Set(g.repayments.map(r=>r.id)).size!==g.repayments.length)throw Error('Duplicate ledger records.');Money.balances(g);}return data;}
function restore(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{if(input.files[0].size>150e6)throw Error('Backup exceeds 150 MB restore limit.');const data=validateBackup(JSON.parse(await input.files[0].text()));const seen=new Set(),restored=data.documents.map(d=>{if(!safeId(d.id)||seen.has(d.id)||typeof d.name!=='string'||typeof d.type!=='string'||!Number.isSafeInteger(d.size)||d.size<0||d.size>20e6||typeof d.created!=='string'||!/^\d{4}-\d{2}-\d{2}T/.test(d.created)||typeof d.favorite!=='boolean'||typeof d.collection!=='string'||(d.collection!==''&&!safeId(d.collection))||typeof d.data!=='string')throw Error('Invalid document.');seen.add(d.id);const raw=atob(d.data);if(raw.length!==d.size)throw Error('Document size does not match.');const {data:encoded,...metadata}=d;return {...metadata,blob:new Blob([Uint8Array.from(raw,c=>c.charCodeAt(0))],{type:d.type})};});if(!confirm('Replace all local Orbit records and files with this backup? Download a current backup first.'))return;await transaction(['state','documents'],tx=>{tx.objectStore('state').put(data.state,'main');const store=tx.objectStore('documents');store.clear();restored.forEach(d=>store.add(d));});await load();closeModal();render();toast('Workspace restored.');}catch(e){toast(e.message||'Could not restore this backup.');}};input.click();}
document.addEventListener('click',async ev=>{const el=ev.target.closest('button');if(!el)return;try{const d=el.dataset;if(d.action){const actions={settings,upload,group:createGroup,expense:()=>addExpense(),repayment:repay,cancel:closeModal,export:exportBackup,restore,persist:async()=>toast(await navigator.storage?.persist?.()?'Persistent storage granted. Keep backups too.':'Browser did not grant persistence. Keep backups.'),collection:()=>formModal('New collection',field('Collection name','<input name="name" required maxlength="80">'),async f=>{const name=f.get('name').trim();if(!name)throw Error('Enter a name.');await mutate(s=>s.collections.push({id:uid(),name}));}),member:()=>formModal('Add a member',field('Member name','<input name="name" required maxlength="60">'),async f=>{const name=f.get('name').trim(),id=group().id;await mutate(s=>{const g=s.groups.find(g=>g.id===id);if(!name||g.members.some(m=>m.name.toLowerCase()===name.toLowerCase()))throw Error('Use a distinct member name.');if(g.members.length>=30)throw Error('Maximum 30 members.');g.members.push({id:uid(),name});});})};await actions[d.action]?.();}else if(d.tab){vaultTab=d.tab;render();}else if('payer'in d){payerFilter=d.payer;render();}else if(d.openCollection){collectionFilter=d.openCollection;vaultTab='all';render();}else if(d.favorite){const doc=docs.find(x=>x.id===d.favorite);await docWrite(s=>s.put({...doc,favorite:!doc.favorite}));}else if(d.preview)await preview(d.preview);else if(d.deleteDoc){if(confirm('Delete this file from this browser?'))await docWrite(s=>s.delete(d.deleteDoc));}else if(d.organize){const doc=docs.find(x=>x.id===d.organize);formModal('Move document',field('Collection',`<select name="collection"><option value="">Unfiled</option>${state.collections.map(c=>`<option value="${c.id}" ${doc.collection===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`),async f=>{await docWrite(s=>s.put({...doc,collection:f.get('collection')}));});}else if(d.deleteCollection){if(confirm('Delete collection? Its documents will remain in My Documents.')){await transaction(['state','documents'],tx=>{const store=tx.objectStore('state'),r=store.get('main');r.onsuccess=()=>{const s=r.result||state;s.collections=s.collections.filter(c=>c.id!==d.deleteCollection);store.put(s,'main');};const ds=tx.objectStore('documents'),cursor=ds.openCursor();cursor.onsuccess=()=>{const c=cursor.result;if(!c)return;if(c.value.collection===d.deleteCollection)c.update({...c.value,collection:''});c.continue();};});await load();render();}}else if(d.detail)detail(d.detail);else if(d.editExpense){const expense=group().expenses.find(e=>e.id===d.editExpense);closeModal();addExpense(expense);}else if(d.deleteExpense||d.deleteRepayment){if(confirm('Delete this ledger entry? Balances will be recalculated.')){const id=group().id;await mutate(s=>{const g=s.groups.find(g=>g.id===id);if(d.deleteExpense)g.expenses=g.expenses.filter(e=>e.id!==d.deleteExpense);else g.repayments=g.repayments.filter(r=>r.id!==d.deleteRepayment);});closeModal();}}}catch(e){toast(e.message||'Could not update storage.');}});
document.addEventListener('change',e=>{if(e.target.id==='group-select'){groupId=e.target.value;payerFilter='';render();}if(e.target.id==='period'){period=e.target.value;render();}if(e.target.id==='collection-filter'){collectionFilter=e.target.value;render();}if(e.target.id==='type-filter'){typeFilter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const cursor=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(cursor,cursor);}});
$('#settings').onclick=settings;$('#theme').onclick=()=>mutate(s=>{s.theme=document.body.classList.contains('dark')?'light':'dark';});$('#close-modal').onclick=closeModal;$('#modal').addEventListener('cancel',()=>{if(previewURL)URL.revokeObjectURL(previewURL);});window.addEventListener('hashchange',()=>{query='';payerFilter='';render();main.focus();});window.addEventListener('focus',async()=>{if(db&&!$('#modal').open){await load();render();}});
(async()=>{try{const r=indexedDB.open('orbit-local-v1',1);r.onupgradeneeded=()=>{r.result.createObjectStore('state');r.result.createObjectStore('documents',{keyPath:'id'});};db=await request(r);await load();render();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{});}catch(e){main.innerHTML=empty('!','Browser storage unavailable','Open Orbit through a local web server or HTTPS in a browser with storage enabled.');}})();
